import React, {useState, useCallback, useRef, useEffect} from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import {cn} from "@/lib/utils";
import {FormContext, type FormContextValue} from "./form.context";
import type {FormAction, PiFormEvents, PiFormProps} from "./form.types";

export const FormComponent = (
  props: PiCardProps<PiFormProps, PiFormEvents>,
): React.ReactNode => {
  const {
    id,
    content = [],
    initialValues = {},
    submitLabel = "Submit",
    hideSubmit = false,
    className,
    cardName,
    onSubmitted,
    onCancelled,
    onAbandoned,
  } = props;

  const [formData, setFormData] = useState<Record<string, unknown>>(() => ({
    ...initialValues,
  }));
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Tracks whether the form reached a "final" state (submitted or
  // explicitly cancelled) so the unmount effect below can tell the
  // difference between that and being torn down some other way (e.g. its
  // parent pi/dialog was dismissed) — the latter fires `onAbandoned`.
  const finalizedRef = useRef(false);
  // Mirrors state in refs so the unmount effect (which only runs once) can
  // read the latest values without re-subscribing on every keystroke.
  const idRef = useRef(id);
  idRef.current = id;
  const formDataRef = useRef(formData);
  formDataRef.current = formData;
  const onAbandonedRef = useRef(onAbandoned);
  onAbandonedRef.current = onAbandoned;

  useEffect(() => {
    return () => {
      if (!finalizedRef.current) {
        onAbandonedRef.current({id: idRef.current, formData: formDataRef.current});
      }
    };
    // Intentionally run only on mount/unmount.

  }, []);

  const handleChange = useCallback((fieldName: string, value: unknown) => {
    setFormData((prev) => ({...prev, [fieldName]: value}));
    // Clear validation error when the user modifies the field
    setErrors((prev) => {
      if (!prev[fieldName]) return prev;
      const next = {...prev};
      delete next[fieldName];
      return next;
    });
  }, []);

  const setError = useCallback((fieldName: string, error: string | null) => {
    setErrors((prev) => {
      if (error === null) {
        const next = {...prev};
        delete next[fieldName];
        return next;
      }
      return {...prev, [fieldName]: error};
    });
  }, []);

  const doSubmit = useCallback(() => {
    finalizedRef.current = true;
    onSubmitted({id, formData});
  }, [id, formData, onSubmitted]);

  const doCancel = useCallback(() => {
    finalizedRef.current = true;
    onCancelled({id, formData});
  }, [id, formData, onCancelled]);

  const handleSubmit = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      doSubmit();
    },
    [doSubmit],
  );

  // Single entry point for any control nested in the form's content to
  // trigger a top-level form action (Button's `formAction`, a field's
  // `submitOnEnter`, etc.) — keeps all form-bindable controls consistent.
  const requestAction = useCallback(
    (action: FormAction) => {
      if (action === "submit") {
        doSubmit();
      } else {
        doCancel();
      }
    },
    [doSubmit, doCancel],
  );

  const contextValue: FormContextValue = {
    formData,
    errors,
    handleChange,
    setError,
    requestAction,
    isInForm: true,
  };

  return (
    <FormContext.Provider value={contextValue}>
      <form
        onSubmit={handleSubmit}
        className={cn("flex flex-col gap-4", className)}
        data-pihanga={cardName}
      >
        {content.map((cref, idx) => (
          <Card key={idx} cardName={cref} parentCard={cardName} />
        ))}
        {!hideSubmit && (
          <button
            type="submit"
            className="inline-flex h-9 items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground shadow transition-colors hover:bg-primary/90 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50"
          >
            {submitLabel}
          </button>
        )}
      </form>
    </FormContext.Provider>
  );
};

import React, {useContext} from "react";
import type {FormAction} from "./form.types";

/**
 * Shape of the data provided by FormContext.
 * When inside a <Form> card, isInForm is true and all fields are populated.
 * When outside (fallback), isInForm is false.
 */
export interface FormContextValue {
  formData: Record<string, unknown>;
  errors: Record<string, string>;
  handleChange: (fieldName: string, value: unknown) => void;
  setError: (fieldName: string, error: string | null) => void;
  /**
   * Call from within form content to request that the enclosing Form
   * perform a top-level action:
   * - `"submit"` — same as pressing the form's native submit button; fires
   *   `onSubmitted`. Used by `Button` (`formAction: "submit"`) and by
   *   form-bindable fields' `submitOnEnter` prop.
   * - `"cancel"` — fires `onCancelled` without submitting or resetting the
   *   form's field values. Used by `Button` (`formAction: "cancel"`).
   */
  requestAction: (action: FormAction) => void;
  isInForm: boolean;
}

const FALLBACK_CONTEXT: FormContextValue = {
  formData: {},
  errors: {},
  handleChange: () => {},
  setError: () => {},
  requestAction: () => {},
  isInForm: false,
};

export const FormContext = React.createContext<FormContextValue | null>(null);

/**
 * Hook that reads the nearest FormContext.
 * Returns a fallback (isInForm=false) when called outside a <Form> card.
 *
 * Usage in field components:
 *   const form = useFormContext();
 *   const value = form.isInForm && name ? form.formData[name] ?? '' : propValue;
 */
export const useFormContext = (): FormContextValue => {
  const ctx = useContext(FormContext);
  return ctx ?? FALLBACK_CONTEXT;
};

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const PI_FORM_CARD = "pi/form";

export const Form = createCardDeclaration<PiFormProps, PiFormEvents>(
  PI_FORM_CARD,
);

export const PI_FORM_ACTION = registerActions(PI_FORM_CARD, [
  "submitted",
  "cancelled",
  "abandoned",
]);

export const onFormSubmitted = createOnAction<PiFormSubmittedEvent>(
  PI_FORM_ACTION.SUBMITTED,
);

/** @deprecated Use `onFormSubmitted` instead. */
export const onPiFormSubmitted = onFormSubmitted;

/**
 * Fires when a control inside the form's content explicitly requests
 * cancellation — see `FormContext.requestAction("cancel")` (wired up
 * automatically for any `Button` card with `formAction: "cancel"`).
 * Does not submit the form and does not reset its field values.
 */
export const onFormCancelled = createOnAction<PiFormCancelledEvent>(
  PI_FORM_ACTION.CANCELLED,
);

/**
 * Fires automatically when the Form card is removed from the screen
 * (unmounted) *without* having been submitted or explicitly cancelled first
 * — e.g. a parent `pi/dialog` is dismissed via the X button, Escape, or an
 * outside click while the form is still open. Use this to clean up any
 * related state (drafts, optimistic UI, etc.) regardless of how the host
 * container went away.
 *
 * Never fires after `onSubmitted` or `onCancelled` for the same form
 * instance.
 */
export const onFormAbandoned = createOnAction<PiFormAbandonedEvent>(
  PI_FORM_ACTION.ABANDONED,
);

/**
 * Shared props for any card that binds a single value to a `pi/form`'s
 * state (text inputs, toggles, selects, etc.).
 *
 * All form-bindable field cards (`pi/input`, `pi/text-field`,
 * `pi/text-area`, `pi/switch`, `pi/checkbox`, `pi/toggle-group`,
 * `pi/select`, …) extend this so the binding contract stays identical
 * everywhere: set `name` to read/write the field via `FormContext` when
 * rendered inside a `pi/form`; omit it (or render outside a form) to fall
 * back to the card's own standalone `value`/`checked` prop + `onChanged`
 * event.
 */
export type FormFieldProps = {
  /**
   * Field name used to bind to FormContext when inside a pi/form card.
   * When provided the component reads its value from form state and writes
   * back via form.handleChange.
   */
  name?: string;
};

/**
 * Actions a control nested inside a `pi/form` can request via
 * `FormContext.requestAction()` — currently used by `Button`'s
 * `formAction` prop, and by form-bindable fields' `submitOnEnter` prop.
 *
 * - `"submit"` — triggers the form's real submit flow (same as pressing its
 *   native submit button), which fires `onSubmitted`.
 * - `"cancel"` — fires `onCancelled` without submitting or resetting the
 *   form.
 */
export type FormAction = "submit" | "cancel";

export type PiFormProps = {
  /**
   * Optional id passed through to events for identification.
   */
  id?: string;

  /**
   * Ordered list of field card refs to render inside the form.
   * Each card (e.g. TextField, Checkbox, FormSelect) will be rendered
   * in order and wrapped by a FormContext.Provider so they can read
   * and write shared form state.
   */
  content?: PiCardRef[];

  /**
   * Initial values for the form fields, keyed by field name.
   */
  initialValues?: Record<string, unknown>;

  /**
   * Label for the submit button.
   * @default "Submit"
   */
  submitLabel?: string;

  /**
   * Additional CSS classes for the <form> element.
   */
  className?: string;

  /**
   * When true, the default footer "Submit" button is not rendered.
   * Use this when the form's own content already provides a way to submit
   * (e.g. a `Button` with `formAction: "submit"`).
   * @default false
   */
  hideSubmit?: boolean;
};

export type PiFormSubmittedEvent = {
  id?: string;
  /** Snapshot of form state at the time of submission. */
  formData: Record<string, unknown>;
};

export type PiFormCancelledEvent = {
  id?: string;
  /** Snapshot of form state at the time of cancellation. */
  formData: Record<string, unknown>;
};

export type PiFormAbandonedEvent = {
  id?: string;
  /** Snapshot of form state at the time the form was removed. */
  formData: Record<string, unknown>;
};

export type PiFormEvents = {
  onSubmitted: PiFormSubmittedEvent;
  onCancelled: PiFormCancelledEvent;
  onAbandoned: PiFormAbandonedEvent;
};

import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {FormComponent} from "./form.component";
import {PI_FORM_ACTION, PI_FORM_CARD} from "./form.types";

export * from "./form.types";
export * from "./form.context";

registerCardComponent({
  name: PI_FORM_CARD,
  component: FormComponent,
  events: actionTypesToEvents(PI_FORM_ACTION),
});
